package controlplane

// Recovery evidence is explicitly excluded from the migration target journal by
// its v3_migration_ prefix. No recovery row is itself a lease or normal receipt.
const migrationRecoverySchema = `
CREATE TABLE v3_migration_recovery_state(id integer PRIMARY KEY CHECK(id=1),generation text NOT NULL UNIQUE,backup_sha256 text NOT NULL,backup_at timestamptz,phase text NOT NULL DEFAULT 'held' CHECK(phase IN ('held','reconciling','ready','complete')),restored_at timestamptz NOT NULL DEFAULT clock_timestamp(),metrics_sha256 text NOT NULL DEFAULT '',isolation_sha256 text NOT NULL DEFAULT '');
CREATE TABLE v3_migration_recovery_nodes(generation text NOT NULL,node text NOT NULL,target jsonb NOT NULL,target_sha256 text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','reading','complete','failed')),reason text NOT NULL DEFAULT '',metrics_state text NOT NULL DEFAULT 'pending',metrics_target_sha256 text NOT NULL DEFAULT '',metrics_sha256 text NOT NULL DEFAULT '',metrics_cache jsonb NOT NULL DEFAULT '[]',metrics_samples bigint NOT NULL DEFAULT 0,metrics_first bigint NOT NULL DEFAULT 0,metrics_last bigint NOT NULL DEFAULT 0,metrics_gaps integer NOT NULL DEFAULT 0,remote_epoch bigint NOT NULL DEFAULT 0,restored_epoch bigint NOT NULL DEFAULT 0,snapshot_sha256 text NOT NULL DEFAULT '',cursor text NOT NULL DEFAULT '',read_events bigint NOT NULL DEFAULT 0,retained_events bigint NOT NULL DEFAULT 0,retention_complete boolean NOT NULL DEFAULT false,notification_unknown bigint NOT NULL DEFAULT 0,evidence jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(generation,node));
CREATE TABLE v3_migration_recovery_events(generation text NOT NULL,node text NOT NULL,id text NOT NULL,payload jsonb NOT NULL,raw_sha256 text NOT NULL,canonical_sha256 text NOT NULL,created_at timestamptz NOT NULL,accepted_at timestamptz,notification_state text NOT NULL CHECK(notification_state IN ('unknown','not_required','verified_unsent','confirmed_delivered','suppressed')),notification_proof text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,PRIMARY KEY(generation,node,id));
CREATE TABLE v3_migration_recovery_notices(generation text NOT NULL,notification bigint NOT NULL,identity_sha256 text NOT NULL,resolution text NOT NULL DEFAULT 'unknown' CHECK(resolution IN ('unknown','verified_unsent','confirmed_delivered','suppressed')),proof text NOT NULL DEFAULT '',PRIMARY KEY(generation,notification));
CREATE INDEX v3_migration_recovery_notice_identity ON v3_migration_recovery_notices(notification,identity_sha256);
`
